#define C(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA:%s:%d\n",cudaGetErrorString(e),__LINE__);exit(7);}}while(0)
template<class T>std::vector<T> rd(std::string s,size_t n){std::ifstream f(s,std::ios::binary);std::vector<T>a(n);f.read((char*)a.data(),n*sizeof(T));if(!f||f.peek()!=EOF){fprintf(stderr,"badasset:%s\n",s.c_str());exit(2);}return a;}
template<class T>struct B{T*base,*p;std::vector<T>init;B(std::vector<T>a,T g){init.assign(16,g);init.insert(init.end(),a.begin(),a.end());init.insert(init.end(),16,g);C(cudaMalloc(&base,init.size()*sizeof(T)));p=base+16;reset();}void reset(){C(cudaMemcpy(base,init.data(),init.size()*sizeof(T),cudaMemcpyHostToDevice));}void append(std::vector<double>&out){std::vector<T>a(init.size());C(cudaMemcpy(a.data(),base,a.size()*sizeof(T),cudaMemcpyDeviceToHost));for(T x:a)out.push_back(x);}~B(){cudaFree(base);}};
#include "study_params.h"
struct Work{int k,nx,ny,T,N,G;float rho,accel,omega,da;std::vector<B<float>*>a,b;B<int>*ob,*pc;B<float>*ps;Work(int id):k(id),nx(NXS[k]),ny(NYS[k]),T(TS[k]),N(nx*ny),G(N/128),rho(RHOS[k]),accel(ACCS[k]),omega(OMS[k]),da(rho*accel){auto f=rd<float>("initial"+std::to_string(k)+"_f32.bin",9*N);for(int q=0;q<9;q++){a.push_back(new B<float>(std::vector<float>(f.begin()+q*N,f.begin()+(q+1)*N),-99));b.push_back(new B<float>(std::vector<float>(N,0),-99));}ob=new B<int>(rd<int>("obstacles"+std::to_string(k)+"_i32.bin",N),-12345);ps=new B<float>(std::vector<float>(G*T,0),-99);pc=new B<int>(std::vector<int>(G*T,0),-12345);}void reset(){for(auto x:a)x->reset();for(auto x:b)x->reset();ob->reset();ps->reset();pc->reset();}void prefix(std::vector<double>&out){out.insert(out.end(),{double(nx),double(ny),double(T),double(rho),double(accel),double(omega),double(da)});for(auto x:a)x->append(out);for(auto x:b)x->append(out);ob->append(out);ps->append(out);pc->append(out);}void tail(std::vector<double>&out){for(auto x:a)x->append(out);for(auto x:b)x->append(out);ps->append(out);pc->append(out);}double run(){std::chrono::steady_clock::time_point start;for(int t=0;t<T;t++){if(t==999){C(cudaDeviceSynchronize());start=std::chrono::steady_clock::now();}d2q9_bgk<<<dim3(nx/128,ny),dim3(128,1)>>>(a[0]->p,a[1]->p,a[2]->p,a[3]->p,a[4]->p,a[5]->p,a[6]->p,a[7]->p,a[8]->p,b[0]->p,b[1]->p,b[2]->p,b[3]->p,b[4]->p,b[5]->p,b[6]->p,b[7]->p,b[8]->p,ob->p,ps->p,pc->p,da,omega,nx,ny,t);C(cudaGetLastError());a.swap(b);}C(cudaDeviceSynchronize());return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();}};
int main(){auto expected=rd<double>("oracle_f64.bin",COUNT);auto exact=rd<unsigned char>("exact_mask_u8.bin",COUNT);std::vector<Work*>w;for(int k=0;k<3;k++)w.push_back(new Work(k));for(auto x:w){x->run();if(x->T%2)x->a.swap(x->b);x->reset();}for(int trial=1;trial<=5;trial++){std::vector<double>out;for(auto x:w){x->reset();x->prefix(out);}if(out.size()!=PREFIX)return 8;double secs=0;for(auto x:w)secs+=x->run();for(auto x:w)x->tail(out);bool good=out.size()==COUNT;double err=0,budget=0;for(size_t i=0;i<out.size();i++){double e=std::abs(out[i]-expected[i]),tol=exact[i]?0:2e-5+2e-4*std::abs(expected[i]);good=good&&std::isfinite(out[i])&&e<=tol;err=std::max(err,e);if(tol)budget=std::max(budget,e/tol);} // Guard/count exactness is also checked by the independent saved-capture auditor.
std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/d2q9_trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*8);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"oracle_budget_fraction\":%.17g,\"jit_excluded\":true,\"timing_region\":\"source_t999_tail_sum3resident_LBM_cases_complete_context\",\"iterations\":3202,\"internal_repeats\":1,\"kernel_launches\":205,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,secs,good?"true":"false",out.size(),err,budget,path.c_str(),out.size());fflush(stdout);for(auto x:w)if(x->T%2)x->a.swap(x->b);if(!good)return 4;}return 0;}
